import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int x = sc.nextInt();
        int y = sc.nextInt();
        int z = sc.nextInt();

        int[] costs = {x, y, z};
        java.util.Arrays.sort(costs);

        int count = 0;
        for (int cost : costs) {
            if (n >= cost) {
                n -= cost;
                count++;
            } else {
                break;
            }
        }

        System.out.println(count);
    }
}
