import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int X = sc.nextInt();
        int Y = sc.nextInt();
        int Z = sc.nextInt();

        int[] costs = {X, Y, Z};
        java.util.Arrays.sort(costs);

        int count = 0;
        int total = 0;

        for (int cost : costs) {
            if (total + cost <= N) {
                total += cost;
                count++;
            } else {
                break;
            }
        }

        System.out.println(count);

        sc.close();
    }
}
